INSERT INTO `resep` (`id_resep`, `nama_menu`, `gambar`, `tipe_gambar`, `deskripsi`, `id_user`) VALUES
(10, 'Nasi goreng', , 'image/jpeg', 'Bahan-bahan:\r\n1 siung bawang putih, iris tipis\r\n1 siung bawang merah, iris tipis\r\n2 buah cabai rawit atau sesuai selera, iris tipis\r\n1 buah cabai merah atau sesuai selera, iris tipis\r\nKecap manis\r\nMinyak goreng\r\nGaram\r\nPenyedap rasa\r\nCara membuat:\r\nPanaskan minyak goreng di wajan, Lalu, tumis bawang putih dan bawang merah hingga harum.\r\nMasukkan nasi dan bahan lainnya. Aduk sampai merata, koreksi rasa, dan sajikan.\r\n\r\n\r\n', 1);
INSERT INTO `resep` (`id_resep`, `nama_menu`, `gambar`, `tipe_gambar`, `deskripsi`, `id_user`) VALUES
(11, 'Martabak', , 'jpeg', 'Bahan martabak:\r\n\r\n250gr tepung terigu\r\n350ml air\r\n1sdm tepung tapioka\r\n2sdm gula pasir\r\n½sdt baking powder\r\n½sdt garam\r\n1sdt vanilla\r\n1 butir telur\r\n1sdt baking soda\r\nMentega secukupnya\r\nGula pasir, sebagai taburan\r\nBahan untuk topping:\r\n\r\n100gr meses coklat\r\n100ml Frisian Flag Susu Kental Manis Full Cream GOLD \r\nCara bikin martabak manis teflon:\r\n\r\nCampur tepung terigu, tapioka, baking powder, garam, gula, dan air aduk rata\r\nDiamkan adonan selama 1 jam\r\nTambahkan telur dan baking soda aduk rata\r\nOles sedikit mentega pada wajan, jika sudah panas tuang adonan martabak, saat setengah matang tuang gula ke atasnya\r\nOles mentega secukupnya\r\nTambahkan topping coklat meses\r\nTambahkan Frisian Flag Susu Kental Manis Full Cream GOLD yang NIKMAT!', 1),
(12, 'Sate ayam', , 'jpeg', 'Bahan\r\nBahan dan bumbu sate ayam Madura:\r\n500 g fillet dada ayam\r\n4 sdm Bango Kecap Manis\r\nMinyak, untuk menggoreng\r\nTusuk sate\r\nBumbu kacang:\r\n200 g kacang tanah\r\n3 butir kemiri\r\n6 siung bawang putih\r\n4 buah cabai merah keriting\r\n4 butir bawang merah\r\n600 ml air\r\n2 sdm gula merah\r\n½ sdm Royco Kaldu Ayam\r\nPelengkap:\r\nLontong\r\nBango Kecap Manis\r\nBawang goreng\r\nAcar mentimun\r\nSambal rawit\r\n\r\nCara masak\r\nIris setebal 1-1,5 cm fillet dada ayam. Lalu potong memanjang. Kemudian potong-potong bentuk kotak kecil. Tusukkan ke tusuk satai sebanyak 5-6 potongan daging ayam per tusuk sate. Sisihkan.\r\n\r\nBumbu kacang: Panaskan minyak, goreng kacang hingga setengah matang. Masukkan kemiri, cabai, dan bawang merah. Goreng hingga kacang matang. Angkat.\r\n\r\nBlender campuran kacang tanah bersama bawang putih. Sisihkan.\r\n\r\nMasak air di atas api sedang hingga mendidih. Masukkan bumbu kacang yang sudah diblender. Aduk rata. Kecilkan api.\r\n\r\nTambahkan gula merah dan Royco Kaldu Ayam. Masak sambil diaduk hingga bumbu kacang mengeluarkan minyak dan tidak langu. Angkat. Ambil minyak yang mengapung di permukaan bumbu kacang untuk bumbu oles sate.\r\n\r\nPanaskan grill pan atau bara api. Lumuri sate ayam dengan 3-4 sdm bumbu kacang. Panggang sate sambil dibalikkan kedua sisinya. Masak hingga setengah matang. Olesi dengan Bango Kecap Manis, panggang hingga matang. Angkat.\r\n\r\nSajikan sate bersama bumbu kacang, lontong, Bango Kecap Manis dan semua bahan pelengkap.', 1);
INSERT INTO `resep` (`id_resep`, `nama_menu`, `gambar`, `tipe_gambar`, `deskripsi`, `id_user`) VALUES
(13, 'Soto', , 'jpeg', 'Bahan\r\n1 ekor ayam kampung, belah 2 bagian\r\n2 L untuk merebus\r\n5 cm lengkuas, memarkan\r\n4 cm jahe, memarkan\r\n3 batang serai, memarkan\r\n10 lembar daun jeruk\r\n2 lembar daun salam\r\n1 sdm Royco Kaldu Ayam\r\n3 sdm minyak, untuk menumis\r\nBumbu halus\r\n6 butir bawang merah\r\n5 siung bawang putih\r\n6 butir kemiri, sangrai\r\n1 sdm ketumbar butiran, sangrai\r\n1 sdt merica putih bubuk\r\n2 cm jahe\r\n2 cm kunyit\r\nIsi\r\n3 butir telur ayam rebus\r\nsuun, seduh air panas, tiriskan\r\ntaoge, seduh air mendidih, tiriskan\r\nkol putih, iris tipis, seduh air mendidih, tiriskan\r\ndaun seledri, iris tipis\r\nPelengkap\r\nkerupuk udang, gerus halus\r\nsambal rawit\r\njeruk nipis, potong-potong\r\nBango Kecap Manis\r\n\r\nCara masak\r\nRebus air dan ayam di atas api kecil hingga empuk. Buang sesekali buih yang mengambang di permukaan kaldu. Angkat.\r\n\r\nAmbil ayam, suwir-suwir, sisihkan.\r\n\r\nPanaskan minyak, tumis bumbu halus, lengkuas, jahe, serai, daun jeruk, daun salam, dan kunyit hingga matang.\r\n\r\nTuang ke dalam kaldu bersama Royco Kaldu Ayam, aduk. Panaskan kembali selama sekitar 10 menit atau hingga bumbu meresap. Angkat.\r\n\r\nMasukkan bahan isi dan daging ayam suwir ke dalam mangkuk saji. Tuang kuah, sajikan bersama pelengkap.', 1),
(14, 'Seblak', , 'jpeg', 'Bahan\r\n300 g ceker ayam\r\n1 L air\r\n2 butir telur ayam, kocok lepas\r\n2 batang caisim, potong 2 cm\r\n50 g taoge\r\n1.5 sdm Bango Kecap Manis\r\n3.25 sdt garam\r\n¼ sdt Royco Kaldu Ayam\r\n¼ sdt merica bubuk\r\n2 sdt gula pasir\r\n2 sdm minyak, untuk menumis\r\nBumbu halus\r\n2 siung bawang putih\r\n3 butir bawang merah\r\n3 cm kencur\r\n1 buah cabai merah besar\r\n4 buah cabai rawit merah\r\n\r\nCara masak\r\nRebus ceker bersama air sampai matang dan empuk. Ukur kaldunya 400 ml. Sisihkan.\r\n\r\nTumis bumbu halus sampai harum. Sisihkan bumbu di sisi wajan. Masukkan telur. Aduk sampai berbutir. Tambahkan ceker dan kerupuk. Aduk rata.\r\n\r\nMasukkan caisim dan taoge. Aduk sampai layu. Tuangkan air rebusan ceker. Aduk rata. Masukkan Bango Kecap Manis. Aduk rata.\r\n\r\nBubuhi garam, Royco Kaldu Ayam, merica bubuk dan gula pasir. Aduk rata. Masak sampai matang.', 1);
INSERT INTO `resep` (`id_resep`, `nama_menu`, `gambar`, `tipe_gambar`, `deskripsi`, `id_user`) VALUES
(15, 'Rendang', , 'jpeg', '1 kg daging sapi\r\n3 butir kelapa, diambil santan kental dan santan encernya\r\n4 lembar daun jeruk\r\n1 lembar daun kunyit, ikat\r\n3 batang serai, memarkan\r\n4 butir asam kandis\r\n2 sdt garam\r\n100 g ambu/kelapa sangrai\r\n1 sdm rempah rendang, siap pakai\r\nBumbu Halus:\r\n250 g cabai merah besar\r\n20 g lengkuas\r\n100 g bawang merah\r\n100 g bawang putih\r\n50 g kemiri\r\n3 cm kunyit\r\n2 cm jahe\r\nCara Memasak:\r\nPotong-potong daging sapi ukuran dadu 3 cm. Sisihkan\r\nTumis Bumbu Halus dengan 4 sdm minyak goreng hingga harum.\r\nMasukkan daun jeruk, serai, daun kunyit, asam kandis, dan garam, lalu aduk rata.\r\nTuangi santan, tambahkan bumbu rempah daging lalu masak hingga mendidih.\r\nMasukkan potongan daging, masak dengan api kecil selama beberapa jam sambil sesekali diaduk hingga santan mengental berminyak dan berwarna kecokelatan agak kering.\r\nAngkat dan dinginkan.\r\n\r\n', 1),
(16, 'Sop ', , 'jpeg', 'Bahan-bahan:\r\n\r\n200gr baso\r\n300ml kaldu sapi\r\n50gr kembang kol\r\n50gr buncis\r\n50gr wortel\r\n2 batang seledri\r\n1 batang daun bawang\r\n200ml susu UHT Frisian Flag Low Fat\r\n2 siung bawang putih\r\n1sdt kaldu bubuk\r\nGaram dan merica bubuk secukupnya\r\nCara membuat:\r\n\r\nTumis 2 siung bawang putih dengan minyak goreng.\r\nSetelah harum masukkan kaldu sapi dan air.\r\nMasukkan kembang kol, wortel, baso, gula, dan garam secukupnya, merica bubuk, serta kaldu bubuk. Masak hingga setengah matang.\r\nTambahkan buncis, seledri, daun bawang iris, susu UHT Frisian Flag Low Fat, masak hingga mendidih.\r\nResep sayur sop baso siap disajikan.', 1);
INSERT INTO `resep` (`id_resep`, `nama_menu`, `gambar`, `tipe_gambar`, `deskripsi`, `id_user`) VALUES
(17, 'Ayam', , 'jpeg', 'Membuat Ayam Goreng Gurih:\r\n1 ekor ayam (atau 1 kg ayam)\r\n16 gram Royco ayam (setara 1 sdm / 3 sdt)\r\n250 ml air mineral\r\n1000 ml minyak goreng (untuk menggoreng)\r\n\r\nCara masak\r\nMasukkan air dalam panci atau wajan.\r\n\r\nMasukkan ayam ke dalam panci yang berisi air dan tuangkan 2 sachet Royco, aduk rata.\r\n\r\nNyalakan api dan rebus hingga mendidih.\r\n\r\nSetelah air mendidih, kecilkan api ke tingkat sedang. Bolak-balikkan ayam menggunakan capitan agar kulit tidak mudah sobek. Tutup panci sambil beberapa kali diaduk. Masak selama 15-20 menit.\r\n\r\nBesarkan api agar air mudah menyusut. Pada tahap ini, sebaiknya ayam tidak ditinggalkan agar tidak gosong. Masak sampai air menyusut, selama kurang lebih 5 menit.\r\n\r\nMatikan api lalu diamkan ayam dalam suhu ruang.\r\n\r\nGoreng ayam dengan minyak panas, pastikan ayam tidak dalam keadaan panas agar hasil gorengan menjadi maksimal. Tiriskan.\r\n\r\nAngkat dan tiriskan, Ayam siap untuk disajikan dengan cita rasa lezat dari bumbu ungkep ayam goreng Royco.', 1);
INSERT INTO `resep` (`id_resep`, `nama_menu`, `gambar`, `tipe_gambar`, `deskripsi`, `id_user`) VALUES
(18, 'Nasi Goreng', , 'jpeg', '5 sdm minyak goreng\r\n2 butir telur (kocok lepas)\r\n500 gr nasi putih\r\n150 gr daging ayam (goreng dan suwir-suwir)\r\n60 gr kol (iris halus)\r\n1 batang daun bawang (iris halus)\r\nBumbu-bumbu\r\n\r\n5 butir bawang merah (haluskan)\r\n3 siung bawang putih (haluskan)\r\n4 buah cabai merah keriting (haluskan)\r\n1 sdm ebi sangrai (haluskan)\r\n2 butir kemiri (haluskan)\r\n3 sdm kecap manis\r\n1/2 sdt lada bubuk\r\n1 sdt garam halus\r\n1 sdm bawang merah goreng\r\nCara Membuat\r\n\r\nPanaskan minyak dan tumis semua bumbu halus.\r\nTunggu hingga aroma harum muncul.\r\nSisihkan terlebih dahulu tumisan bumbu di bagian pinggir wajan.\r\nMasukkan kocokan telur, orak-arik hingga telur berwujud bulir.\r\nMasukkan nasi putih, daging ayam suwir, kol, daun bawang, kecap manis, dan bumbu lain.\r\nMasak bersamaan dengan bumbu tadi dan aduk hingga merata.\r\nSetelah matang, tuang nasi goreng ke dalam piring.\r\nHidangkan selagi hangat dengan diberi taburan bawang merah goreng, irisan tomat segar, hingga daun selada segar.\r\n\r\n', 1);
INSERT INTO `resep` (`id_resep`, `nama_menu`, `gambar`, `tipe_gambar`, `deskripsi`, `id_user`) VALUES
(19, 'Gepuk', , 'jpeg', 'Bahan :\r\n500 g daging has sapi\r\n4 cm lengkuas parut\r\n2 lembar daun salam\r\n2 sdm kecap manis\r\n1 sdm gula Jawa serut halus\r\n1/2 sdt asam Jawa\r\n500 ml santan segar\r\n1 sdm kaldu bubuk\r\nBumbu Halus:\r\n7 butir bawang merah\r\n5 siung bawang putih\r\n1 sdm ketumbar sangrai\r\n3 butir kemiri\r\n2 sdt garam\r\nTaburan:\r\nbawang merah goreng\r\nCara Membuat Gepuk Daging Khas Sunda:\r\nDidihkan air secukupnya lalu rebus daging hingga mendidih beberapa saat. Angkat daging dan buang air perebusnya.\r\nRebus air penggantinya dalam panci, rebus daging hingga empuk. Angkat dan sisihkan.\r\nPotong daging searah dgn serat seteal 3/4 cm, pukul pukul dengan ulekan atau pemukul daging hingga daging melebar dan empuk.\r\nMasukkan daging beserta Bumbu Halus ke dalam wajan bersama sisa air perebusnya.\r\nTambahkan kaldu bubuk, daun salam, lengkuas parut, asam Jawa, gula merah, kecap dan santan.\r\nMasak hingga air menyusut dan bumbu meresap lalu angkat daging.\r\nSiapkan wajan bersih, goreng daging dengan api yang kecil hingga berwarna cokelat keemasan.\r\nAngkat dan taburi bawang merah goreng.\r\n\r\n', 1);

